mapper.update:
UPDATE schedule
SET
    schedule_title = #{params.scheduleTitle},
    schedule_content = #{params.scheduleContent},
    schedule_start = #{params.scheduleStart},
    schedule_end = #{params.scheduleEnd}
WHERE schedule_id = #{params.scheduleId}
AND employee_id = #{employeeId}
AND (schedule_type = 'PERSONAL' OR schedule_type = 'COMMON')

mapper.delete:
DELETE FROM schedule
WHERE schedule_id = #{scheduleId}
AND employee_id = #{employeeId}
AND schedule_type = #{scheduleType}
